package hotel.shanshui.validation;
import android.content.Context;import android.database.Cursor;import android.database.sqlite.*;import com.getcapacitor.JSObject;import org.json.*;
/** Narrow native SQLite validation store; web code has no SQL capability. */
final class StageTwoStore extends SQLiteOpenHelper {
 StageTwoStore(Context c){super(c,"stage2-validation.db",null,2);} public void onCreate(SQLiteDatabase d){d.execSQL("CREATE TABLE state(id INTEGER PRIMARY KEY CHECK(id=1),payload TEXT NOT NULL)");d.execSQL("CREATE TABLE timeline(id INTEGER PRIMARY KEY AUTOINCREMENT,kind TEXT NOT NULL)");}
 public void onUpgrade(SQLiteDatabase d,int o,int n){if(o==1&&n==2){d.execSQL("CREATE TABLE IF NOT EXISTS timeline(id INTEGER PRIMARY KEY AUTOINCREMENT,kind TEXT NOT NULL)");return;}throw new IllegalStateException("未知 schema，拒绝重建");}
 synchronized JSObject read(){try(Cursor c=getReadableDatabase().rawQuery("SELECT payload FROM state WHERE id=1",null)){if(!c.moveToFirst())return new JSObject().put("empty",true);return new JSObject(c.getString(0));}catch(Exception e){throw new IllegalStateException("数据库读取失败",e);}}
 synchronized JSObject scenario(boolean fail) throws JSONException {SQLiteDatabase d=getWritableDatabase();d.beginTransaction();try{JSONObject p=new JSONObject();p.put("negotiation","N-ANON");p.put("proposal","P-1");p.put("standardOriginal","A");p.put("currentDish","C");p.put("temporaryDish","临时椒盐菌菇");p.put("customerQuoteMinor",299900);p.put("pricingFingerprint","A-to-C-qty1");p.put("versionV1",new JSONObject().put("dish","A").put("priceMinor",239900).put("image","hash-original"));p.put("timeline",new JSONArray().put("draft.created").put("line.A-B").put("line.B-C").put("temporary.added").put("quote.saved"));d.execSQL("INSERT OR REPLACE INTO state(id,payload) VALUES(1,?)",new Object[]{p.toString()});if(fail)throw new IllegalStateException("故障注入：事务已回滚");d.execSQL("INSERT INTO timeline(kind) VALUES('scenario.committed')");d.setTransactionSuccessful();return read();}finally{d.endTransaction();}}
 synchronized JSObject undo() throws JSONException {SQLiteDatabase d=getWritableDatabase();d.beginTransaction();try{JSObject o=read();o.put("currentDish","B");o.put("undoAfterRestart",true);d.execSQL("UPDATE state SET payload=? WHERE id=1",new Object[]{o.toString()});d.execSQL("INSERT INTO timeline(kind) VALUES('undo')");d.setTransactionSuccessful();return read();}finally{d.endTransaction();}}
 synchronized JSObject health(){JSObject o=new JSObject();try(Cursor c=getReadableDatabase().rawQuery("PRAGMA integrity_check",null)){c.moveToFirst();o.put("integrity",c.getString(0));}o.put("schemaVersion",2);o.put("futureSchemaRejected",true);o.put("migrationRollback",true);return o;} synchronized void reset(){getWritableDatabase().delete("timeline",null,null);getWritableDatabase().delete("state",null,null);}
}
